INSERT INTO `site_setting` (`setting_key`, `value_json`, `updated_by`) VALUES
  ('about', '{"institution_name":"海珠区安全教育培训中心","platform_subtitle":"安全教育培训与考试平台","version":"1.2.0","contact_email":"","wechat_account":"","contact_phone":"","service_terms":{"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"海珠区安全教育培训中心服务使用协议"}]},{"type":"paragraph","content":[{"type":"text","text":"欢迎使用海珠区安全教育培训中心在线教育平台（以下简称“本平台”）。请您仔细阅读以下条款："}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"一、服务内容"}]},{"type":"paragraph","content":[{"type":"text","text":"本平台提供在线课程学习、在线考试、成绩查询、错题回顾等教育信息化服务。平台保留根据实际情况调整服务内容、变更服务方式的权利。"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"二、用户义务"}]},{"type":"paragraph","content":[{"type":"text","text":"1. 用户注册时应提供真实、准确的个人信息，如有变更应及时更新。"}]},{"type":"paragraph","content":[{"type":"text","text":"2. 用户应妥善保管账号和密码，因账号密码泄露导致的损失由用户自行承担。"}]},{"type":"paragraph","content":[{"type":"text","text":"3. 用户不得利用本平台从事任何违法违规活动，不得传播病毒、恶意代码或进行任何可能破坏平台正常运行的行为。"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"三、知识产权"}]},{"type":"paragraph","content":[{"type":"text","text":"本平台提供的所有内容，包括但不限于课程资料、试题、软件、技术等，知识产权归本平台所有。未经书面许可，任何单位或个人不得以任何方式复制、传播、修改或用于商业用途。"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"四、隐私保护"}]},{"type":"paragraph","content":[{"type":"text","text":"本平台重视用户隐私保护，收集的用户个人信息仅用于提供教育服务，不会向第三方披露，法律法规另有规定的除外。"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"五、免责声明"}]},{"type":"paragraph","content":[{"type":"text","text":"1. 本平台尽力保证服务的稳定性和连续性，但不对因不可抗力、系统维护、网络故障等原因导致的服务中断承担责任。"}]},{"type":"paragraph","content":[{"type":"text","text":"2. 用户理解并同意，使用本平台服务所存在的风险由用户自行承担。"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"六、协议修改"}]},{"type":"paragraph","content":[{"type":"text","text":"本平台有权根据需要修改本协议条款，修改后的协议一经发布即生效。如用户不同意修改后的协议，应停止使用本平台服务。"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"七、法律适用"}]},{"type":"paragraph","content":[{"type":"text","text":"本协议的订立、执行和解释均适用中华人民共和国法律。如发生争议，双方应友好协商解决；协商不成的，提交平台所在地有管辖权的人民法院诉讼解决。"}]}]}}', NULL)
ON DUPLICATE KEY UPDATE `setting_key` = `setting_key`;
